Haz doble clic para conectar y clic derecho para más opciones

// Cada línea completa del servidor
mud.on(Events.Line, event => {
    if (event.text.startsWith("Obvious exits:")) {
        mud.echo(event.text);
    }
});

// Datos estructurados del servidor (si están disponibles)
mud.on(Events.Gmcp, event => {
    if (event.package === "Char.Vitals" && event.data) {
        mud.echo(JSON.stringify(event.data));
    }
});

mud.alias(/^lh$/, () => mud.send("look"));
mud.trigger(/^Exits: (.+)$/, match => mud.echo(match[1]));
// mud.every(60, () => mud.echo("60s"));

// Detectar salidas
mud.on(Events.Line, event => {
    if (event.text.startsWith("Exits:") || event.text.startsWith("Obvious exits:")) {
        mud.echo(event.text);
    }
});

mud.alias(/^lh$/, () => mud.send("look"));
